package com.nextaicommerce.platform.config;
import java.util.*;import java.util.concurrent.ScheduledFuture;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.runner.ApplicationContextRunner;import org.springframework.scheduling.TaskScheduler;import org.springframework.scheduling.annotation.ScheduledAnnotationBeanPostProcessor;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LocalAmazonReadSchedulingTest {
 final String[] safe={"spring.profiles.active=fee-release-uat","spring.datasource.url=jdbc:postgresql://127.0.0.1:55432/canonical_fixture","app.amazon.local-read-only-scheduling=true","app.scheduling.enabled=false","spring.flyway.enabled=false","app.integrations.external-enabled=true","app.amazon.sync-enabled=true","app.amazon.recurring-enabled=true","app.amazon.recipient-import-enabled=true","app.shopify.orders.only-scheduling=false","app.shopify.orders.polling-enabled=false","app.amazon.fee-pilot.only-scheduling=false","app.amazon.variation.trial-only-scheduling=false","app.amazon.write-enabled=false","app.amazon.listing-actions-enabled=false","app.amazon.inventory-publication-enabled=false","app.amazon.shelf-sale-enabled=false","app.amazon.buy-shipping-enabled=false","app.fedex.confirmation-enabled=false","app.shopify.inventory.write-enabled=false","app.shopify.prices.write-enabled=false","app.shopify.sale-prices.write-enabled=false","app.mail.enabled=false"};
 ApplicationContextRunner runner(){var scheduler=mock(TaskScheduler.class,i->ScheduledFuture.class.isAssignableFrom(i.getMethod().getReturnType())?mock(ScheduledFuture.class):RETURNS_DEFAULTS.answer(i));return new ApplicationContextRunner().withUserConfiguration(LocalAmazonReadSchedulingConfiguration.class).withBean(TaskScheduler.class,()->scheduler);}
 @Test void absentFlagCreatesNoScheduler(){runner().run(c->assertThat(c).doesNotHaveBean(ScheduledAnnotationBeanPostProcessor.class));}
 @Test void onlyFiveExistingReadAndRetentionTasksRegistered(){runner().withPropertyValues(safe).run(c->{assertThat(c).hasNotFailed();var p=c.getBean(ScheduledAnnotationBeanPostProcessor.class);var jdbc=mock(org.springframework.jdbc.core.JdbcTemplate.class);var api=mock(com.nextaicommerce.platform.sync.AmazonSpApiClient.class);var worker=new com.nextaicommerce.platform.sync.AmazonSyncWorker(mock(com.nextaicommerce.platform.sync.AmazonSyncStore.class),api,mock(com.nextaicommerce.platform.sync.AmazonReportNormalizer.class),mock(com.nextaicommerce.platform.marketplace.MarketplaceSkuAutoMapper.class),mock(com.nextaicommerce.platform.orders.OrderRepository.class),true);Object recurring;try{var ctor=com.nextaicommerce.platform.sync.AmazonRecurringSyncScheduler.class.getDeclaredConstructors()[0];ctor.setAccessible(true);recurring=ctor.newInstance(jdbc,mock(org.springframework.transaction.support.TransactionTemplate.class),true);}catch(Exception e){throw new AssertionError(e);}var recipient=new com.nextaicommerce.platform.shipping.OrderRecipientWorker(jdbc,mock(com.nextaicommerce.platform.shipping.OrderRecipientService.class),mock(com.nextaicommerce.platform.shipping.OrderRecipientRepository.class),true);p.postProcessAfterInitialization(worker,"reads");p.postProcessAfterInitialization(recurring,"recurring");p.postProcessAfterInitialization(recipient,"recipient");p.postProcessAfterInitialization(mock(com.nextaicommerce.platform.shopify.ShopifyOrderPolling.class),"shopify");p.postProcessAfterInitialization(mock(com.nextaicommerce.platform.sync.InventoryPublicationSimulation.class),"simulation");assertThat(p.getScheduledTasks()).hasSize(5);verifyNoInteractions(jdbc,api);});}
 @Test void everyGuardIsMandatoryAndConflictingSchedulersFailClosed(){for(String property:safe){if(property.startsWith("spring.profiles"))property="spring.profiles.active=production";else if(property.startsWith("spring.datasource"))property="spring.datasource.url=jdbc:postgresql://remote.invalid:5432/production";else if(property.startsWith("app.amazon.local-read-only"))continue;else property=property.substring(0,property.indexOf('=')+1)+(property.endsWith("true")?"false":"true");runner().withPropertyValues(safe).withPropertyValues(property).run(c->assertThat(c).hasFailed());}}
 @Test void unknownMethodsAndOtherWorkersAreNeverPermitted(){assertThat(LocalAmazonReadSchedulingConfiguration.permitted(com.nextaicommerce.platform.sync.AmazonSyncWorker.class,"other")).isFalse();assertThat(LocalAmazonReadSchedulingConfiguration.permitted(com.nextaicommerce.platform.shipping.CarrierShipmentConfirmation.class,"process")).isFalse();assertThat(LocalAmazonReadSchedulingConfiguration.permitted(com.nextaicommerce.platform.shopify.ShopifyOrderPolling.class,"tick")).isFalse();}
}
